edits.before:
        self._onKeyChange = function(e)
{
    e = e || window.event;

    if (self.isVisible()) {

        switch(e.keyCode){
            case 13:
            case 27:
                if (opts.field) {
                    opts.field.blur();
                }
                break;
            case 37:
                self.adjustDate('subtract', 1);
                break;
            case 38:
                self.adjustDate('subtract', 7);
                break;
            case 39:
                self.adjustDate('add', 1);
                break;
            case 40:
                self.adjustDate('add', 7);
                break;
            case 8:
            case 46:
                self.setDate(null);
                break;
        }
    }
};

edits.after:
        self._onKeyChange = function(e)
{
    e = e || window.event;

    if (self.isVisible()) {

        switch(e.keyCode){
            case 13:
            case 27:
                if (opts.field) {
                    opts.field.blur();
                }
                break;
            case 37:
                self._adjustDateSkipDisabled('subtract', 1);
                break;
            case 38:
                self._adjustDateSkipDisabled('subtract', 7);
                break;
            case 39:
                self._adjustDateSkipDisabled('add', 1);
                break;
            case 40:
                self._adjustDateSkipDisabled('add', 7);
                break;
            case 8:
            case 46:
                self.setDate(null);
                break;
        }
    }
};

        self._adjustDateSkipDisabled = function(sign, days)
{
    var difference = parseInt(days)*24*60*60*1000;
    var newDate = this.getDate() || new Date();
    var candidate;
    if (sign === 'add') {
        candidate = new Date(newDate.valueOf() + difference);
    } else {
        candidate = new Date(newDate.valueOf() - difference);
    }
    while (!this._isDateSelectable(candidate)) {
        if (sign === 'add') {
            candidate = new Date(candidate.valueOf() + difference);
        } else {
            candidate = new Date(candidate.valueOf() - difference);
        }
    }
    this.setDate(candidate);
};

        self._isDateSelectable = function(date)
{
    var opts = this._o;
    if (opts.minDate && date < opts.minDate) return false;
    if (opts.maxDate && date > opts.maxDate) return false;
    if (opts.disableWeekends && (date.getDay() === 0 || date.getDay() === 6)) return false;
    if (opts.disableDayFn && opts.disableDayFn(date)) return false;
    return true;
};
